-- ================================================================
-- CCR POC - TRADE DATA (richer product mix, exposure-reconciling)
-- Full replace of star_dim_trade. Every asset class now has
-- multiple product types, so the Asset Class -> Product Type drill
-- shows real depth for any counterparty.
-- Per VM agreement, trade_exposure_contribution sums EXACTLY to
-- direct exposure on 2026-03-31.
-- ================================================================

-- star_dim_trade needs the contribution column (safe if it exists):
ALTER TABLE `d4001-centralus-tdvip-creditrisk`.xvala_xva.star_dim_trade
  ADD COLUMNS (trade_exposure_contribution DECIMAL(18,2)
    COMMENT 'Share of counterparty direct exposure as-of 2026-03-31.');

